const listInventoryAlertCounts = `-- name: ListInventoryAlertCounts :many

WITH lots AS (
    SELECT b.organization_id,
           count(*) FILTER (WHERE l.expiry_date < $1::date) AS expired,
           count(*) FILTER (WHERE l.expiry_date >= $1::date
                              AND l.expiry_date <= $1::date + i.expiry_alert_days) AS expiring
    FROM inventory_balances b
    JOIN inventory_lots l ON l.id = b.lot_id
    JOIN inventory_items i ON i.id = b.item_id
    WHERE b.quantity > 0 AND l.expiry_date IS NOT NULL
    GROUP BY b.organization_id
), low AS (
    SELECT i.organization_id, count(*) AS below
    FROM inventory_items i
    WHERE i.is_active AND i.min_stock IS NOT NULL
      AND COALESCE((SELECT sum(quantity) FROM inventory_balances b WHERE b.item_id = i.id), 0) < i.min_stock
    GROUP BY i.organization_id
)
SELECT COALESCE(lots.organization_id, low.organization_id)::uuid AS organization_id,
       COALESCE(lots.expired, 0)::int AS expired_lot_count,
       COALESCE(lots.expiring, 0)::int AS expiring_lot_count,
       COALESCE(low.below, 0)::int AS below_min_count
FROM lots
FULL JOIN low ON low.organization_id = lots.organization_id
WHERE COALESCE(lots.expired, 0) + COALESCE(lots.expiring, 0) + COALESCE(low.below, 0) > 0
`

type ListInventoryAlertCountsRow struct {
	OrganizationID   pgtype.UUID `json:"organization_id"`
	ExpiredLotCount  int32       `json:"expired_lot_count"`
	ExpiringLotCount int32       `json:"expiring_lot_count"`
	BelowMinCount    int32       `json:"below_min_count"`
}

// ============ Günlük stok uyarısı ============
// Firma başına: SKT'si geçmiş ve yaklaşan (bakiyesi olan) partiler,
// minimum stoğun altındaki aktif kartlar. Yalnızca en az biri olanlar.
func (q *Queries) ListInventoryAlertCounts(ctx context.Context, today pgtype.Date) ([]ListInventoryAlertCountsRow, error) {
	rows, err := q.db.Query(ctx, listInventoryAlertCounts, today)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListInventoryAlertCountsRow
	for rows.Next() {
		var i ListInventoryAlertCountsRow
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ExpiredLotCount,
			&i.ExpiringLotCount,
			&i.BelowMinCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

